            ];

            $article = Article::firstOrCreate(
                ['title_en' => $articleAttributes['title_en']],
                $articleAttributes
            );

            foreach ($comments as $comm) {
                $article->comments()->firstOrCreate(
                    ['user_name' => $comm['user_name'], 'comment' => $comm['comment']],
                    ['is_approved' => true]
                );
            }
        }
    }
}
